    [8.6, 0.4], [9.1, 0.7], [9.5, 0.4], [9.2, 0.15],
    [8.3, 0.8], [9.7, 0.9], [9.0, 1.1], [9.4, 1.3],
  ];
  dotData.forEach(([x, y]) => {
    s.addShape(pres.shapes.OVAL, { x, y, w: 0.18, h: 0.18, fill: { color: C.teal, transparency: 55 }, line: { color: C.teal, transparency: 55 } });
  });

  // Title
  s.addText("THE POWER OF VACCINATION", {
    x: 0.5, y: 1.0, w: 9.0, h: 0.65,
    fontSize: 36, fontFace: "Georgia", bold: true,
    color: C.white, align: "left", valign: "top", margin: 0, charSpacing: 2,
  });

  s.addText("From Smallpox Eradication to COVID-19 in Record Time", {
    x: 0.5, y: 1.75, w: 8.5, h: 0.75,
    fontSize: 22, fontFace: "Calibri", bold: false, italic: true,
    color: C.mint, align: "left", valign: "top", margin: 0,
  });

  // Divider
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 2.65, w: 4.0, h: 0.04, fill: { color: C.seafoam }, line: { color: C.seafoam } });

