  s.addText("Other vaccines", { x: 7.05, y: 5.08, w: 1.4, h: 0.22, fontSize: 10, color: C.textMid, margin: 0 });
  s.addShape(pres.shapes.RECTANGLE, { x: 8.45, y: 5.1, w: 0.18, h: 0.18, fill: { color: C.gold }, line: { color: C.gold } });
  s.addText("COVID-19", { x: 8.7, y: 5.08, w: 1.0, h: 0.22, fontSize: 10, bold: true, color: C.alert, margin: 0 });

  s.addText("Source: Our World in Data", {
    x: 0.3, y: 5.35, w: 4, h: 0.2, fontSize: 9, color: C.textLight, margin: 0,
  });
}

