  s.addText("Key Takeaways: Vaccines Have Eliminated Deadly Diseases — But the Job Isn't Done", {
    x: 0.35, y: 0, w: 9.3, h: 0.75,
    fontSize: 15, fontFace: "Georgia", bold: true, color: C.navy,
    align: "left", valign: "middle", margin: 0,
