    {
      num: "01",
      head: "100% Elimination Achieved",
      body: "Diphtheria, smallpox, and acute polio have been 100% eliminated in the US — cases and deaths reached zero.",
    },
    {
      num: "02",
      head: "Development Timelines Collapsed",
      body: "From 105 years (typhoid) to under 1 year (COVID-19), driven by mRNA technology and genomic tools.",
    },
    {
      num: "03",
      head: "Herd Immunity Protects Communities",
