      num: "05",
      head: "Coverage Gaps Persist",
      body: "Pneumococcal (40.5% case reduction), hepatitis A (89%), and hepatitis B (83.9%) still require stronger coverage.",
    },
  ];

  takeaways.forEach((t, i) => {
    const ty = 0.88 + i * 0.86;
    // Number badge
    s.addShape(pres.shapes.OVAL, {
      x: 0.3, y: ty + 0.02, w: 0.44, h: 0.44,
      fill: { color: C.teal }, line: { color: C.teal },
    });
    s.addText(t.num, {
      x: 0.3, y: ty + 0.02, w: 0.44, h: 0.44,
      fontSize: 11, fontFace: "Calibri", bold: true, color: C.white,
      align: "center", valign: "middle", margin: 0,
    });
    s.addText(t.head, {
      x: 0.88, y: ty, w: 4.4, h: 0.36,
      fontSize: 13, fontFace: "Calibri", bold: true, color: C.mint,
      align: "left", valign: "middle", margin: 0,
    });
    s.addText(t.body, {
      x: 0.88, y: ty + 0.36, w: 4.4, h: 0.42,
      fontSize: 11, fontFace: "Calibri", color: "B8D4D9",
      align: "left", valign: "top", margin: 0,
    });
  });

  // Right column: call to action box
  s.addShape(pres.shapes.RECTANGLE, {
    x: 5.6, y: 0.88, w: 4.0, h: 4.2,
    fill: { color: "0D3B52" }, line: { color: C.teal, pt: 1.5 },
    shadow: makeShadow(),
  });

  s.addText("Call to Action", {
    x: 5.75, y: 0.98, w: 3.7, h: 0.45,
    fontSize: 16, fontFace: "Georgia", bold: true, color: C.seafoam,
    align: "center", margin: 0,
