const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "The Power of Vaccination: From Smallpox Eradication to COVID-19 in Record Time";

// ── Color palette (Ocean/Teal health theme) ──────────────────────────────────
const C = {
  navy:      "0B2545",   // dominant dark bg
  teal:      "1B7F8E",   // secondary
  seafoam:   "02A89E",   // accent
  mint:      "A8DADC",   // light accent
  cream:     "F4F9FA",   // light bg
  white:     "FFFFFF",
  gold:      "E9C46A",   // highlight / callout
  alert:     "E63946",   // gaps / warnings
  textDark:  "1B2B3A",
  textMid:   "3D5A6C",
  textLight: "7FA0AE",
  rowAlt:    "EAF4F5",
};

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.12 });

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 1 — Title
// ─────────────────────────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.navy };

  // Left accent stripe
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.22, h: 5.625, fill: { color: C.seafoam }, line: { color: C.seafoam } });

  // Subtle dot pattern top-right (decorative circles)
  const dotData = [
    [8.6, 0.4], [9.1, 0.7], [9.5, 0.4], [9.2, 0.15],
    [8.3, 0.8], [9.7, 0.9], [9.0, 1.1], [9.4, 1.3],
  ];
  dotData.forEach(([x, y]) => {
    s.addShape(pres.shapes.OVAL, { x, y, w: 0.18, h: 0.18, fill: { color: C.teal, transparency: 55 }, line: { color: C.teal, transparency: 55 } });
  });

  // Title
  s.addText("THE POWER OF VACCINATION", {
    x: 0.5, y: 1.0, w: 9.0, h: 0.65,
    fontSize: 36, fontFace: "Georgia", bold: true,
    color: C.white, align: "left", valign: "top", margin: 0, charSpacing: 2,
  });

  s.addText("From Smallpox Eradication to COVID-19 in Record Time", {
    x: 0.5, y: 1.75, w: 8.5, h: 0.75,
    fontSize: 22, fontFace: "Calibri", bold: false, italic: true,
    color: C.mint, align: "left", valign: "top", margin: 0,
  });

  // Divider
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 2.65, w: 4.0, h: 0.04, fill: { color: C.seafoam }, line: { color: C.seafoam } });

  // Scope line
  s.addText("A data-driven overview of vaccine impact on public health  ·  1796–2020", {
    x: 0.5, y: 2.85, w: 8.5, h: 0.45,
    fontSize: 14, fontFace: "Calibri", color: C.textLight,
    align: "left", margin: 0,
  });

  // Bottom attribution
  s.addText("Source: Our World in Data — ourworldindata.org/vaccination", {
    x: 0.5, y: 5.1, w: 9.0, h: 0.35,
    fontSize: 11, fontFace: "Calibri", color: C.textLight, align: "left", margin: 0,
  });

  // Audience
  s.addText("For public health professionals and policy analysts", {
    x: 0.5, y: 4.75, w: 9.0, h: 0.3,
    fontSize: 11, fontFace: "Calibri", italic: true, color: C.textLight, align: "left", margin: 0,
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 2 — Vaccine Timeline Acceleration (horizontal bar chart)
// ─────────────────────────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.cream };

  // Title bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.75, fill: { color: C.navy }, line: { color: C.navy } });
  s.addText("From 100 Years to Under 1 Year: Vaccine Development Is Accelerating", {
    x: 0.35, y: 0, w: 9.3, h: 0.75,
    fontSize: 18, fontFace: "Georgia", bold: true, color: C.white,
    align: "left", valign: "middle", margin: 0,
  });

  // Data: diseases ordered longest → shortest
  const diseases = [
    { label: "Typhoid Fever",   years: 105, covid: false },
    { label: "Meningitis",      years: 92,  covid: false },
    { label: "Ebola",           years: 43,  covid: false },
    { label: "Whooping Cough",  years: 42,  covid: false },
    { label: "Chickenpox",      years: 42,  covid: false },
    { label: "Polio",           years: 47,  covid: false },
    { label: "Hepatitis B",     years: 16,  covid: false },
    { label: "Measles",         years: 10,  covid: false },
    { label: "COVID-19",        years: 1,   covid: true  },
  ];

  const chartStartX = 2.5;
  const chartAreaW  = 7.0;
  const maxYears    = 110;
  const rowH        = 0.38;
  const startY      = 0.95;
  const barH        = 0.26;

  // Vertical grid lines
  [0, 25, 50, 75, 100].forEach(v => {
    const bx = chartStartX + (v / maxYears) * chartAreaW;
    s.addShape(pres.shapes.LINE, {
      x: bx, y: startY - 0.05, w: 0, h: diseases.length * rowH + 0.2,
      line: { color: "CBD5E1", width: 0.5, dashType: "dash" },
    });
    s.addText(v === 0 ? "" : `${v}y`, {
      x: bx - 0.2, y: startY + diseases.length * rowH + 0.08,
      w: 0.4, h: 0.22, fontSize: 9, color: C.textLight, align: "center", margin: 0,
    });
  });

  diseases.forEach((d, i) => {
    const y = startY + i * rowH;
    const barW = Math.max((d.years / maxYears) * chartAreaW, 0.08);
    const fillColor = d.covid ? C.gold : C.teal;
    const labelColor = d.covid ? C.textDark : C.textDark;

    // Row zebra bg
    if (i % 2 === 0) {
      s.addShape(pres.shapes.RECTANGLE, {
        x: 0.3, y: y - 0.02, w: 9.4, h: rowH,
        fill: { color: "E8F4F6" }, line: { color: "E8F4F6" },
      });
    }

    // Disease label
    s.addText(d.label, {
      x: 0.3, y: y + 0.03, w: 2.1, h: barH,
      fontSize: 11, fontFace: "Calibri", color: C.textDark,
      align: "right", valign: "middle", margin: 0,
    });

    // Bar
    s.addShape(pres.shapes.RECTANGLE, {
      x: chartStartX, y: y + 0.03, w: barW, h: barH,
      fill: { color: fillColor }, line: { color: fillColor },
      shadow: d.covid ? makeShadow() : undefined,
    });

    // Years label
    const labelText = d.covid ? "< 1 year  ★ RECORD" : `${d.years} years`;
    s.addText(labelText, {
      x: chartStartX + barW + 0.08, y: y + 0.03, w: 2.0, h: barH,
      fontSize: d.covid ? 11 : 10, fontFace: "Calibri",
      bold: d.covid, color: d.covid ? C.alert : C.textMid,
      align: "left", valign: "middle", margin: 0,
    });
  });

  // X-axis label
  s.addText("Years from pathogen identification to vaccine licensure", {
    x: 2.5, y: 4.75, w: 7.0, h: 0.3,
    fontSize: 10, fontFace: "Calibri", italic: true, color: C.textLight,
    align: "center", margin: 0,
  });

  // Legend
  s.addShape(pres.shapes.RECTANGLE, { x: 6.8, y: 5.1, w: 0.18, h: 0.18, fill: { color: C.teal }, line: { color: C.teal } });
  s.addText("Other vaccines", { x: 7.05, y: 5.08, w: 1.4, h: 0.22, fontSize: 10, color: C.textMid, margin: 0 });
  s.addShape(pres.shapes.RECTANGLE, { x: 8.45, y: 5.1, w: 0.18, h: 0.18, fill: { color: C.gold }, line: { color: C.gold } });
  s.addText("COVID-19", { x: 8.7, y: 5.08, w: 1.0, h: 0.22, fontSize: 10, bold: true, color: C.alert, margin: 0 });

  s.addText("Source: Our World in Data", {
    x: 0.3, y: 5.35, w: 4, h: 0.2, fontSize: 9, color: C.textLight, margin: 0,
  });
