    fontSize: 18, fontFace: "Georgia", bold: true, color: C.white,
    align: "left", valign: "middle", margin: 0,
  });

  // ── Diagram: 3 scenarios side by side ────────────────────────────────────
  // Helper: draw a person circle
  function addPerson(slide, cx, cy, type) {
    // type: "vacc" | "unvacc" | "vulnerable" | "infected"
    const colors = {
      vacc:       { fill: C.seafoam, border: C.teal,  label: "V" },
      unvacc:     { fill: "D1D5DB",  border: "9CA3AF", label: "U" },
      vulnerable: { fill: "FEF3C7",  border: C.gold,  label: "!" },
      infected:   { fill: C.alert,   border: "C0392B", label: "✕" },
    };
    const c = colors[type];
    const r = 0.25;
    slide.addShape(pres.shapes.OVAL, {
      x: cx - r, y: cy - r, w: r * 2, h: r * 2,
      fill: { color: c.fill }, line: { color: c.border, pt: 1.5 },
    });
    slide.addText(c.label, {
      x: cx - r, y: cy - r, w: r * 2, h: r * 2,
      fontSize: 10, fontFace: "Calibri", bold: true, color: C.navy,
      align: "center", valign: "middle", margin: 0,
    });
  }

  // Scenario 1: No vaccination — disease spreads
  const s1x = 0.4;
  s.addText("No Vaccination", {
    x: s1x, y: 0.85, w: 2.9, h: 0.35,
    fontSize: 12, fontFace: "Calibri", bold: true, color: C.alert,
    align: "center", margin: 0,
  });
  s.addShape(pres.shapes.RECTANGLE, { x: s1x, y: 1.2, w: 2.9, h: 2.9, fill: { color: "FFF0F0" }, line: { color: "FECACA", pt: 1 } });
  const grid1 = [
    ["infected", "infected",   "unvacc"],
    ["infected", "vulnerable", "infected"],
    ["unvacc",   "infected",   "infected"],
  ];
  grid1.forEach((row, ri) => row.forEach((t, ci) => {
    addPerson(s, s1x + 0.48 + ci * 0.97, 1.58 + ri * 0.84, t);
  }));
  s.addText("Disease spreads freely", { x: s1x, y: 4.15, w: 2.9, h: 0.35, fontSize: 10, color: C.alert, align: "center", italic: true, margin: 0 });

  // Scenario 2: Partial vaccination — still some spread
  const s2x = 3.55;
  s.addText("Partial Vaccination", {
    x: s2x, y: 0.85, w: 2.9, h: 0.35,
    fontSize: 12, fontFace: "Calibri", bold: true, color: C.gold,
    align: "center", margin: 0,
  });
  s.addShape(pres.shapes.RECTANGLE, { x: s2x, y: 1.2, w: 2.9, h: 2.9, fill: { color: "FFFBEB" }, line: { color: "FDE68A", pt: 1 } });
  const grid2 = [
    ["vacc",    "infected",   "vacc"],
    ["vacc",    "vulnerable", "infected"],
    ["unvacc",  "vacc",       "vacc"],
  ];
  grid2.forEach((row, ri) => row.forEach((t, ci) => {
    addPerson(s, s2x + 0.48 + ci * 0.97, 1.58 + ri * 0.84, t);
  }));
  s.addText("Sporadic spread — some risk remains", { x: s2x, y: 4.15, w: 2.9, h: 0.35, fontSize: 10, color: "D97706", align: "center", italic: true, margin: 0 });

  // Scenario 3: Herd immunity — vulnerable protected
  const s3x = 6.7;
  s.addText("Herd Immunity Achieved", {
    x: s3x, y: 0.85, w: 2.9, h: 0.35,
    fontSize: 12, fontFace: "Calibri", bold: true, color: C.teal,
    align: "center", margin: 0,
  });
  s.addShape(pres.shapes.RECTANGLE, { x: s3x, y: 1.2, w: 2.9, h: 2.9, fill: { color: "F0FDFA" }, line: { color: C.mint, pt: 1 } });
  const grid3 = [
    ["vacc",  "vacc",        "vacc"],
    ["vacc",  "vulnerable",  "vacc"],
    ["vacc",  "vacc",        "vacc"],
  ];
  grid3.forEach((row, ri) => row.forEach((t, ci) => {
    addPerson(s, s3x + 0.48 + ci * 0.97, 1.58 + ri * 0.84, t);
  }));
  s.addText("Pathogen cannot spread — vulnerable shielded", { x: s3x, y: 4.15, w: 2.9, h: 0.35, fontSize: 10, color: C.teal, align: "center", italic: true, margin: 0 });

