    { type: "unvacc",     color: "9CA3AF",  label: "Unvaccinated" },
    { type: "vulnerable", color: C.gold,    label: "Vulnerable (cannot be vaccinated)" },
    { type: "infected",   color: C.alert,   label: "Infected" },
