  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.75, fill: { color: C.navy }, line: { color: C.navy } });
  s.addText("Smallpox: The Only Human Disease Eradicated Through Vaccination", {
    x: 0.35, y: 0, w: 9.3, h: 0.75,
    fontSize: 18, fontFace: "Georgia", bold: true, color: C.white,
    align: "left", valign: "middle", margin: 0,
  });

  // Left column: timeline
  const events = [
    { year: "1796", desc: "Edward Jenner creates first vaccine using cowpox to trigger immunity against smallpox." },
    { year: "1959", desc: "WHO passes resolution to eradicate smallpox globally." },
    { year: "1967", desc: "WHO launches intensified eradication campaign worldwide." },
    { year: "1977", desc: "Last natural smallpox case recorded in Somalia." },
    { year: "1980", desc: "WHO certifies global eradication — the only human disease eliminated through vaccination." },
  ];

  events.forEach((e, i) => {
    const y = 0.95 + i * 0.82;

    // Year badge
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.35, y, w: 0.78, h: 0.42,
      fill: { color: i === 4 ? C.seafoam : C.teal }, line: { color: i === 4 ? C.seafoam : C.teal },
    });
    s.addText(e.year, {
      x: 0.35, y, w: 0.78, h: 0.42,
      fontSize: 13, fontFace: "Georgia", bold: true, color: C.white,
      align: "center", valign: "middle", margin: 0,
    });

    // Connecting line (except last)
    if (i < events.length - 1) {
      s.addShape(pres.shapes.LINE, {
        x: 0.74, y: y + 0.42, w: 0, h: 0.4,
        line: { color: C.teal, width: 1.5 },
      });
    }

    // Description
    s.addText(e.desc, {
      x: 1.3, y: y, w: 3.9, h: 0.52,
      fontSize: 12, fontFace: "Calibri", color: C.textDark,
      align: "left", valign: "middle", margin: 0,
    });
  });

  // Right column: why smallpox was eradicable
  s.addShape(pres.shapes.RECTANGLE, {
    x: 5.5, y: 0.9, w: 4.1, h: 4.2,
    fill: { color: "E0F2F3" }, line: { color: C.mint },
    shadow: makeShadow(),
  });

  s.addText("Why Smallpox Was Uniquely Eradicable", {
    x: 5.65, y: 0.98, w: 3.8, h: 0.45,
    fontSize: 14, fontFace: "Georgia", bold: true, color: C.navy,
    align: "center", valign: "middle", margin: 0,
  });

  const reasons = [
    { icon: "●", text: "Infected humans only — no animal reservoir to sustain transmission" },
    { icon: "●", text: "Visible, distinguishable symptoms made case identification straightforward" },
    { icon: "●", text: "Vaccine was cheap, stable, and highly effective" },
    { icon: "●", text: "Global political will aligned behind WHO campaign" },
  ];

  reasons.forEach((r, i) => {
    s.addText([
      { text: r.icon + "  ", options: { color: C.seafoam, bold: true } },
      { text: r.text,         options: { color: C.textDark } },
    ], {
      x: 5.65, y: 1.58 + i * 0.7, w: 3.8, h: 0.6,
      fontSize: 12, fontFace: "Calibri", align: "left", valign: "top", margin: 0,
    });
  });

  s.addShape(pres.shapes.RECTANGLE, {
    x: 5.65, y: 4.42, w: 3.8, h: 0.48,
    fill: { color: C.teal }, line: { color: C.teal },
  });
  s.addText("Certified eradicated 1980 · No human cases since 1977", {
    x: 5.65, y: 4.42, w: 3.8, h: 0.48,
    fontSize: 12, fontFace: "Calibri", bold: true, color: C.white,
    align: "center", valign: "middle", margin: 0,
  });

  s.addText("Source: Our World in Data", {
    x: 0.35, y: 5.35, w: 4, h: 0.2, fontSize: 9, color: C.textLight, margin: 0,
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 6 — Herd Immunity Mechanism
// ─────────────────────────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.cream };

  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.75, fill: { color: C.navy }, line: { color: C.navy } });
  s.addText("Herd Immunity: How Vaccinating Many Protects the Most Vulnerable", {
    x: 0.35, y: 0, w: 9.3, h: 0.75,
    fontSize: 18, fontFace: "Georgia", bold: true, color: C.white,
    align: "left", valign: "middle", margin: 0,
  });

  // ── Diagram: 3 scenarios side by side ────────────────────────────────────
  // Helper: draw a person circle
  function addPerson(slide, cx, cy, type) {
    // type: "vacc" | "unvacc" | "vulnerable" | "infected"
    const colors = {
      vacc:       { fill: C.seafoam, border: C.teal,  label: "V" },
      unvacc:     { fill: "D1D5DB",  border: "9CA3AF", label: "U" },
      vulnerable: { fill: "FEF3C7",  border: C.gold,  label: "!" },
      infected:   { fill: C.alert,   border: "C0392B", label: "✕" },
    };
    const c = colors[type];
    const r = 0.25;
    slide.addShape(pres.shapes.OVAL, {
      x: cx - r, y: cy - r, w: r * 2, h: r * 2,
      fill: { color: c.fill }, line: { color: c.border, pt: 1.5 },
    });
    slide.addText(c.label, {
      x: cx - r, y: cy - r, w: r * 2, h: r * 2,
      fontSize: 10, fontFace: "Calibri", bold: true, color: C.navy,
      align: "center", valign: "middle", margin: 0,
    });
  }

  // Scenario 1: No vaccination — disease spreads
  const s1x = 0.4;
  s.addText("No Vaccination", {
    x: s1x, y: 0.85, w: 2.9, h: 0.35,
    fontSize: 12, fontFace: "Calibri", bold: true, color: C.alert,
    align: "center", margin: 0,
  });
  s.addShape(pres.shapes.RECTANGLE, { x: s1x, y: 1.2, w: 2.9, h: 2.9, fill: { color: "FFF0F0" }, line: { color: "FECACA", pt: 1 } });
  const grid1 = [
    ["infected", "infected",   "unvacc"],
    ["infected", "vulnerable", "infected"],
    ["unvacc",   "infected",   "infected"],
  ];
  grid1.forEach((row, ri) => row.forEach((t, ci) => {
    addPerson(s, s1x + 0.48 + ci * 0.97, 1.58 + ri * 0.84, t);
  }));
  s.addText("Disease spreads freely", { x: s1x, y: 4.15, w: 2.9, h: 0.35, fontSize: 10, color: C.alert, align: "center", italic: true, margin: 0 });

  // Scenario 2: Partial vaccination — still some spread
  const s2x = 3.55;
  s.addText("Partial Vaccination", {
    x: s2x, y: 0.85, w: 2.9, h: 0.35,
    fontSize: 12, fontFace: "Calibri", bold: true, color: C.gold,
    align: "center", margin: 0,
  });
  s.addShape(pres.shapes.RECTANGLE, { x: s2x, y: 1.2, w: 2.9, h: 2.9, fill: { color: "FFFBEB" }, line: { color: "FDE68A", pt: 1 } });
  const grid2 = [
    ["vacc",    "infected",   "vacc"],
    ["vacc",    "vulnerable", "infected"],
    ["unvacc",  "vacc",       "vacc"],
  ];
  grid2.forEach((row, ri) => row.forEach((t, ci) => {
    addPerson(s, s2x + 0.48 + ci * 0.97, 1.58 + ri * 0.84, t);
  }));
  s.addText("Sporadic spread — some risk remains", { x: s2x, y: 4.15, w: 2.9, h: 0.35, fontSize: 10, color: "D97706", align: "center", italic: true, margin: 0 });

  // Scenario 3: Herd immunity — vulnerable protected
  const s3x = 6.7;
  s.addText("Herd Immunity Achieved", {
    x: s3x, y: 0.85, w: 2.9, h: 0.35,
    fontSize: 12, fontFace: "Calibri", bold: true, color: C.teal,
    align: "center", margin: 0,
  });
  s.addShape(pres.shapes.RECTANGLE, { x: s3x, y: 1.2, w: 2.9, h: 2.9, fill: { color: "F0FDFA" }, line: { color: C.mint, pt: 1 } });
  const grid3 = [
    ["vacc",  "vacc",        "vacc"],
    ["vacc",  "vulnerable",  "vacc"],
    ["vacc",  "vacc",        "vacc"],
  ];
  grid3.forEach((row, ri) => row.forEach((t, ci) => {
    addPerson(s, s3x + 0.48 + ci * 0.97, 1.58 + ri * 0.84, t);
  }));
  s.addText("Pathogen cannot spread — vulnerable shielded", { x: s3x, y: 4.15, w: 2.9, h: 0.35, fontSize: 10, color: C.teal, align: "center", italic: true, margin: 0 });

  // Legend
  const legY = 4.62;
  const legItems = [
    { type: "vacc",       color: C.seafoam, label: "Vaccinated" },
    { type: "unvacc",     color: "9CA3AF",  label: "Unvaccinated" },
    { type: "vulnerable", color: C.gold,    label: "Vulnerable (cannot be vaccinated)" },
    { type: "infected",   color: C.alert,   label: "Infected" },
  ];
  legItems.forEach((li, i) => {
    const lx = 0.35 + i * 2.3;
    s.addShape(pres.shapes.OVAL, { x: lx, y: legY + 0.08, w: 0.22, h: 0.22, fill: { color: li.color }, line: { color: li.color } });
    s.addText(li.label, { x: lx + 0.28, y: legY + 0.04, w: 1.9, h: 0.3, fontSize: 9.5, color: C.textDark, margin: 0 });
  });

  // Footnote
  s.addText("Vulnerable individuals: newborns, immunocompromised patients, cancer patients on chemotherapy", {
    x: 0.35, y: 5.2, w: 9.3, h: 0.3,
    fontSize: 9.5, fontFace: "Calibri", italic: true, color: C.textLight,
    align: "center", margin: 0,
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 7 — Remaining Challenges
// ─────────────────────────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.cream };

  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.75, fill: { color: C.alert }, line: { color: C.alert } });
  s.addText("Gaps Persist: Pneumococcal Disease Shows Only 40% Case Reduction", {
    x: 0.35, y: 0, w: 9.3, h: 0.75,
    fontSize: 18, fontFace: "Georgia", bold: true, color: C.white,
    align: "left", valign: "middle", margin: 0,
  });

  // Left: incomplete disease data cards
  const gaps = [
    { disease: "Pneumococcal Disease", case: "40.5%", death: "31.3%", note: "Largest remaining gap" },
    { disease: "Acute Hepatitis B",    case: "83.9%", death: "83.6%", note: "Still ~44 cases/million/yr" },
    { disease: "Hepatitis A",          case: "89%",   death: "88.7%", note: "Still ~51 cases/million/yr" },
  ];

  gaps.forEach((g, i) => {
    const cx = 0.4 + i * 3.15;
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: 0.88, w: 2.85, h: 2.35,
      fill: { color: C.white }, line: { color: "FECACA", pt: 1.5 },
      shadow: makeShadow(),
    });
    // Top accent
    s.addShape(pres.shapes.RECTANGLE, { x: cx, y: 0.88, w: 2.85, h: 0.12, fill: { color: C.alert }, line: { color: C.alert } });

    s.addText(g.disease, {
      x: cx + 0.12, y: 1.04, w: 2.6, h: 0.4,
      fontSize: 12, fontFace: "Calibri", bold: true, color: C.textDark,
      align: "left", margin: 0,
    });
    s.addText("Case reduction", { x: cx + 0.12, y: 1.52, w: 1.3, h: 0.28, fontSize: 10, color: C.textLight, margin: 0 });
    s.addText(g.case, { x: cx + 1.5, y: 1.45, w: 1.2, h: 0.35, fontSize: 18, fontFace: "Georgia", bold: true, color: C.alert, align: "right", margin: 0 });
    s.addText("Death reduction", { x: cx + 0.12, y: 1.88, w: 1.3, h: 0.28, fontSize: 10, color: C.textLight, margin: 0 });
    s.addText(g.death, { x: cx + 1.5, y: 1.82, w: 1.2, h: 0.35, fontSize: 18, fontFace: "Georgia", bold: true, color: "E07B54", align: "right", margin: 0 });
    s.addText(g.note, {
      x: cx + 0.12, y: 2.88, w: 2.6, h: 0.28,
      fontSize: 9.5, italic: true, color: C.textLight, align: "left", margin: 0,
    });
  });

  // Right block removed — barrier cards below span full width ─────────────
  // Barrier cards
  const barriers = [
    { icon: "◆", head: "Access & Supply",    body: "Not everyone globally has access to vaccines; supply shortages put children at risk." },
    { icon: "◆", head: "Scientific Literacy", body: "Poor understanding of vaccines can reduce trust and uptake in communities." },
    { icon: "◆", head: "Coverage Gaps",       body: "Incomplete vaccination coverage leaves populations vulnerable to preventable disease." },
  ];

  barriers.forEach((b, i) => {
    const bx = 0.4 + i * 3.15;
    s.addShape(pres.shapes.RECTANGLE, {
      x: bx, y: 3.38, w: 2.85, h: 1.65,
      fill: { color: "FFF5F5" }, line: { color: "FECACA", pt: 0.75 },
    });
    s.addText([
      { text: b.icon + "  ", options: { color: C.alert, bold: true, fontSize: 12 } },
      { text: b.head,         options: { color: C.textDark, bold: true, fontSize: 12 } },
      { text: "\n" + b.body,  options: { color: C.textMid, fontSize: 11 } },
    ], {
      x: bx + 0.12, y: 3.44, w: 2.6, h: 1.5,
      fontFace: "Calibri", align: "left", valign: "top", margin: 0,
    });
  });

  s.addText("Source: Roush & Murphy (2007) via Our World in Data", {
    x: 0.35, y: 5.38, w: 9.3, h: 0.2, fontSize: 9, color: C.textLight, align: "right", margin: 0,
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 8 — Key Takeaways & Call to Action
// ─────────────────────────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.navy };

  // Top bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.75, fill: { color: C.seafoam }, line: { color: C.seafoam } });
  s.addText("Key Takeaways: Vaccines Have Eliminated Deadly Diseases — But the Job Isn't Done", {
    x: 0.35, y: 0, w: 9.3, h: 0.75,
    fontSize: 15, fontFace: "Georgia", bold: true, color: C.navy,
    align: "left", valign: "middle", margin: 0,
  });

  // Takeaways: left column
  const takeaways = [
    {
      num: "01",
      head: "100% Elimination Achieved",
      body: "Diphtheria, smallpox, and acute polio have been 100% eliminated in the US — cases and deaths reached zero.",
    },
    {
      num: "02",
      head: "Development Timelines Collapsed",
      body: "From 105 years (typhoid) to under 1 year (COVID-19), driven by mRNA technology and genomic tools.",
    },
    {
      num: "03",
      head: "Herd Immunity Protects Communities",
      body: "High vaccination rates shield newborns, immunocompromised individuals, and others who cannot be vaccinated.",
    },
    {
      num: "04",
      head: "Smallpox: The Only Human Disease Eradicated",
      body: "Certified eradicated in 1980 after a global WHO campaign — no natural cases since 1977.",
    },
    {
      num: "05",
      head: "Coverage Gaps Persist",
      body: "Pneumococcal (40.5% case reduction), hepatitis A (89%), and hepatitis B (83.9%) still require stronger coverage.",
    },
  ];

  takeaways.forEach((t, i) => {
    const ty = 0.88 + i * 0.86;
    // Number badge
    s.addShape(pres.shapes.OVAL, {
      x: 0.3, y: ty + 0.02, w: 0.44, h: 0.44,
      fill: { color: C.teal }, line: { color: C.teal },
    });
    s.addText(t.num, {
      x: 0.3, y: ty + 0.02, w: 0.44, h: 0.44,
      fontSize: 11, fontFace: "Calibri", bold: true, color: C.white,
      align: "center", valign: "middle", margin: 0,
    });
    s.addText(t.head, {
      x: 0.88, y: ty, w: 4.4, h: 0.36,
      fontSize: 13, fontFace: "Calibri", bold: true, color: C.mint,
      align: "left", valign: "middle", margin: 0,
    });
    s.addText(t.body, {
      x: 0.88, y: ty + 0.36, w: 4.4, h: 0.42,
      fontSize: 11, fontFace: "Calibri", color: "B8D4D9",
      align: "left", valign: "top", margin: 0,
    });
  });

  // Right column: call to action box
  s.addShape(pres.shapes.RECTANGLE, {
    x: 5.6, y: 0.88, w: 4.0, h: 4.2,
    fill: { color: "0D3B52" }, line: { color: C.teal, pt: 1.5 },
    shadow: makeShadow(),
  });

  s.addText("Call to Action", {
    x: 5.75, y: 0.98, w: 3.7, h: 0.45,
    fontSize: 16, fontFace: "Georgia", bold: true, color: C.seafoam,
    align: "center", margin: 0,
  });

  s.addShape(pres.shapes.LINE, {
    x: 5.95, y: 1.5, w: 3.3, h: 0,
    line: { color: C.teal, width: 1 },
  });

  const ctas = [
    "Strengthen global vaccine supply chains to prevent shortages",
    "Expand coverage for pneumococcal, hepatitis A & B to close remaining gaps",
    "Invest in public trust through science communication and community engagement",
    "Leverage mRNA platform innovation to accelerate future outbreak response",
  ];

  ctas.forEach((c, i) => {
    s.addText([
      { text: "→  ", options: { color: C.seafoam, bold: true } },
      { text: c,     options: { color: C.white } },
    ], {
      x: 5.75, y: 1.62 + i * 0.72, w: 3.7, h: 0.65,
      fontSize: 11.5, fontFace: "Calibri", align: "left", valign: "top", margin: 0,
    });
  });

  // Bottom attribution
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.35, w: 10, h: 0.28, fill: { color: "071A24" }, line: { color: "071A24" } });
  s.addText("Data sourced from Our World in Data — ourworldindata.org/vaccination  ·  Based on Roush & Murphy (2007)", {
    x: 0.35, y: 5.35, w: 9.3, h: 0.28,
    fontSize: 9, fontFace: "Calibri", color: C.textLight,
    align: "center", valign: "middle", margin: 0,
  });
}

// ─────────────────────────────────────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("✅ Saved: /app/output/final_deck.pptx"))
  .catch(e => { console.error("ERROR:", e); process.exit(1); });

