    { label: "Measles",         years: 10,  covid: false },
    { label: "COVID-19",        years: 1,   covid: true  },
  ];

  const chartStartX = 2.5;
  const chartAreaW  = 7.0;
  const maxYears    = 110;
  const rowH        = 0.38;
  const startY      = 0.95;
  const barH        = 0.26;

  // Vertical grid lines
  [0, 25, 50, 75, 100].forEach(v => {
    const bx = chartStartX + (v / maxYears) * chartAreaW;
    s.addShape(pres.shapes.LINE, {
      x: bx, y: startY - 0.05, w: 0, h: diseases.length * rowH + 0.2,
      line: { color: "CBD5E1", width: 0.5, dashType: "dash" },
    });
    s.addText(v === 0 ? "" : `${v}y`, {
      x: bx - 0.2, y: startY + diseases.length * rowH + 0.08,
      w: 0.4, h: 0.22, fontSize: 9, color: C.textLight, align: "center", margin: 0,
    });
  });

  diseases.forEach((d, i) => {
    const y = startY + i * rowH;
    const barW = Math.max((d.years / maxYears) * chartAreaW, 0.08);
    const fillColor = d.covid ? C.gold : C.teal;
    const labelColor = d.covid ? C.textDark : C.textDark;

    // Row zebra bg
    if (i % 2 === 0) {
      s.addShape(pres.shapes.RECTANGLE, {
        x: 0.3, y: y - 0.02, w: 9.4, h: rowH,
        fill: { color: "E8F4F6" }, line: { color: "E8F4F6" },
      });
    }

    // Disease label
    s.addText(d.label, {
      x: 0.3, y: y + 0.03, w: 2.1, h: barH,
      fontSize: 11, fontFace: "Calibri", color: C.textDark,
      align: "right", valign: "middle", margin: 0,
    });

    // Bar
    s.addShape(pres.shapes.RECTANGLE, {
      x: chartStartX, y: y + 0.03, w: barW, h: barH,
      fill: { color: fillColor }, line: { color: fillColor },
      shadow: d.covid ? makeShadow() : undefined,
    });

    // Years label
    const labelText = d.covid ? "< 1 year  ★ RECORD" : `${d.years} years`;
    s.addText(labelText, {
      x: chartStartX + barW + 0.08, y: y + 0.03, w: 2.0, h: barH,
      fontSize: d.covid ? 11 : 10, fontFace: "Calibri",
      bold: d.covid, color: d.covid ? C.alert : C.textMid,
      align: "left", valign: "middle", margin: 0,
    });
  });

  // X-axis label
  s.addText("Years from pathogen identification to vaccine licensure", {
    x: 2.5, y: 4.75, w: 7.0, h: 0.3,
    fontSize: 10, fontFace: "Calibri", italic: true, color: C.textLight,
    align: "center", margin: 0,
  });

  // Legend
  s.addShape(pres.shapes.RECTANGLE, { x: 6.8, y: 5.1, w: 0.18, h: 0.18, fill: { color: C.teal }, line: { color: C.teal } });
  s.addText("Other vaccines", { x: 7.05, y: 5.08, w: 1.4, h: 0.22, fontSize: 10, color: C.textMid, margin: 0 });
  s.addShape(pres.shapes.RECTANGLE, { x: 8.45, y: 5.1, w: 0.18, h: 0.18, fill: { color: C.gold }, line: { color: C.gold } });
  s.addText("COVID-19", { x: 8.7, y: 5.08, w: 1.0, h: 0.22, fontSize: 10, bold: true, color: C.alert, margin: 0 });

  s.addText("Source: Our World in Data", {
    x: 0.3, y: 5.35, w: 4, h: 0.2, fontSize: 9, color: C.textLight, margin: 0,
  });
}

