  // Footnote
  s.addText("Vulnerable individuals: newborns, immunocompromised patients, cancer patients on chemotherapy", {
    x: 0.35, y: 5.2, w: 9.3, h: 0.3,
    fontSize: 9.5, fontFace: "Calibri", italic: true, color: C.textLight,
    align: "center", margin: 0,
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 7 — Remaining Challenges
// ─────────────────────────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.cream };

  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.75, fill: { color: C.alert }, line: { color: C.alert } });
  s.addText("Gaps Persist: Pneumococcal Disease Shows Only 40% Case Reduction", {
    x: 0.35, y: 0, w: 9.3, h: 0.75,
    fontSize: 18, fontFace: "Georgia", bold: true, color: C.white,
    align: "left", valign: "middle", margin: 0,
  });

  // Left: incomplete disease data cards
  const gaps = [
    { disease: "Pneumococcal Disease", case: "40.5%", death: "31.3%", note: "Largest remaining gap" },
    { disease: "Acute Hepatitis B",    case: "83.9%", death: "83.6%", note: "Still ~44 cases/million/yr" },
    { disease: "Hepatitis A",          case: "89%",   death: "88.7%", note: "Still ~51 cases/million/yr" },
  ];

  gaps.forEach((g, i) => {
    const cx = 0.4 + i * 3.15;
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: 0.88, w: 2.85, h: 2.35,
      fill: { color: C.white }, line: { color: "FECACA", pt: 1.5 },
      shadow: makeShadow(),
    });
    // Top accent
    s.addShape(pres.shapes.RECTANGLE, { x: cx, y: 0.88, w: 2.85, h: 0.12, fill: { color: C.alert }, line: { color: C.alert } });

    s.addText(g.disease, {
      x: cx + 0.12, y: 1.04, w: 2.6, h: 0.4,
      fontSize: 12, fontFace: "Calibri", bold: true, color: C.textDark,
      align: "left", margin: 0,
    });
    s.addText("Case reduction", { x: cx + 0.12, y: 1.52, w: 1.3, h: 0.28, fontSize: 10, color: C.textLight, margin: 0 });
    s.addText(g.case, { x: cx + 1.5, y: 1.45, w: 1.2, h: 0.35, fontSize: 18, fontFace: "Georgia", bold: true, color: C.alert, align: "right", margin: 0 });
    s.addText("Death reduction", { x: cx + 0.12, y: 1.88, w: 1.3, h: 0.28, fontSize: 10, color: C.textLight, margin: 0 });
    s.addText(g.death, { x: cx + 1.5, y: 1.82, w: 1.2, h: 0.35, fontSize: 18, fontFace: "Georgia", bold: true, color: "E07B54", align: "right", margin: 0 });
    s.addText(g.note, {
      x: cx + 0.12, y: 2.88, w: 2.6, h: 0.28,
      fontSize: 9.5, italic: true, color: C.textLight, align: "left", margin: 0,
    });
  });

  // Right block removed — barrier cards below span full width ─────────────
  // Barrier cards
  const barriers = [
    { icon: "◆", head: "Access & Supply",    body: "Not everyone globally has access to vaccines; supply shortages put children at risk." },
    { icon: "◆", head: "Scientific Literacy", body: "Poor understanding of vaccines can reduce trust and uptake in communities." },
    { icon: "◆", head: "Coverage Gaps",       body: "Incomplete vaccination coverage leaves populations vulnerable to preventable disease." },
  ];

  barriers.forEach((b, i) => {
    const bx = 0.4 + i * 3.15;
    s.addShape(pres.shapes.RECTANGLE, {
      x: bx, y: 3.38, w: 2.85, h: 1.65,
      fill: { color: "FFF5F5" }, line: { color: "FECACA", pt: 0.75 },
    });
    s.addText([
      { text: b.icon + "  ", options: { color: C.alert, bold: true, fontSize: 12 } },
