      fontSize: 11, fontFace: "Calibri", color: "B8D4D9",
      align: "left", valign: "top", margin: 0,
    });
  });

  // Right column: call to action box
  s.addShape(pres.shapes.RECTANGLE, {
    x: 5.6, y: 0.88, w: 4.0, h: 4.2,
    fill: { color: "0D3B52" }, line: { color: C.teal, pt: 1.5 },
    shadow: makeShadow(),
  });

  s.addText("Call to Action", {
    x: 5.75, y: 0.98, w: 3.7, h: 0.45,
    fontSize: 16, fontFace: "Georgia", bold: true, color: C.seafoam,
    align: "center", margin: 0,
  });

  s.addShape(pres.shapes.LINE, {
    x: 5.95, y: 1.5, w: 3.3, h: 0,
    line: { color: C.teal, width: 1 },
  });

  const ctas = [
    "Strengthen global vaccine supply chains to prevent shortages",
    "Expand coverage for pneumococcal, hepatitis A & B to close remaining gaps",
    "Invest in public trust through science communication and community engagement",
    "Leverage mRNA platform innovation to accelerate future outbreak response",
