const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "The Power of Vaccination: From Smallpox Eradication to COVID-19 in Record Time";

// ── Color palette (Ocean/Teal health theme) ──────────────────────────────────
const C = {
  navy:      "0B2545",   // dominant dark bg
  teal:      "1B7F8E",   // secondary
  seafoam:   "02A89E",   // accent
  mint:      "A8DADC",   // light accent
  cream:     "F4F9FA",   // light bg
  white:     "FFFFFF",
  gold:      "E9C46A",   // highlight / callout
  alert:     "E63946",   // gaps / warnings
  textDark:  "1B2B3A",
  textMid:   "3D5A6C",
  textLight: "7FA0AE",
  rowAlt:    "EAF4F5",
};

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.12 });

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 1 — Title
// ─────────────────────────────────────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.navy };

  // Left accent stripe
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.22, h: 5.625, fill: { color: C.seafoam }, line: { color: C.seafoam } });

  // Subtle dot pattern top-right (decorative circles)
  const dotData = [
    [8.6, 0.4], [9.1, 0.7], [9.5, 0.4], [9.2, 0.15],
    [8.3, 0.8], [9.7, 0.9], [9.0, 1.1], [9.4, 1.3],
  ];
  dotData.forEach(([x, y]) => {
    s.addShape(pres.shapes.OVAL, { x, y, w: 0.18, h: 0.18, fill: { color: C.teal, transparency: 55 }, line: { color: C.teal, transparency: 55 } });
  });

  // Title
  s.addText("THE POWER OF VACCINATION", {
    x: 0.5, y: 1.0, w: 9.0, h: 0.65,
    fontSize: 36, fontFace: "Georgia", bold: true,
    color: C.white, align: "left", valign: "top", margin: 0, charSpacing: 2,
  });

  s.addText("From Smallpox Eradication to COVID-19 in Record Time", {
    x: 0.5, y: 1.75, w: 8.5, h: 0.75,
    fontSize: 22, fontFace: "Calibri", bold: false, italic: true,
    color: C.mint, align: "left", valign: "top", margin: 0,
  });

  // Divider
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 2.65, w: 4.0, h: 0.04, fill: { color: C.seafoam }, line: { color: C.seafoam } });

  // Scope line

